sql.where:
${boardAlias}.board_type_id = #{boardTypeId}
AND ${boardAlias}.state = false

    AND ${boardAlias}.created_date >= #{search.startDate}
    AND ${boardAlias}.created_date < DATE_ADD(#{search.endDate}, INTERVAL 1 DAY)


    AND ${boardAlias}.category_id = #{search.categoryId}


    AND (${boardAlias}.title LIKE CONCAT('%', #{search.searchWord}, '%')
    OR ${boardAlias}.content LIKE CONCAT('%', #{search.searchWord}, '%')
    OR ${memberAlias}.member_name LIKE CONCAT('%', #{search.searchWord}, '%'))

mapper.select:
SELECT COUNT(*) FROM ( SELECT 1 FROM board b JOIN thumbnail th ON th.board_id = b.id
JOIN member m ON m.id = b.member_id
) t
